### Mengelompokkan per kategori

Ambil daftar kategori yang unik dengan `Set`, lalu untuk setiap kategori saring produknya:

```jsx
const kategori = [...new Set(produk.map((p) => p.kategori))];
// ['Minuman', 'Makanan']

{kategori.map((k) => (
  <Bagian key={k} judul={k}>
    {produk
      .filter((p) => p.kategori === k)
      .map((p) => <KartuProduk key={p.id} {...p} />)}
  </Bagian>
))}
```

Ada dua `map` bertingkat, masing-masing dengan key sendiri: nama kategori untuk `Bagian`, id untuk `KartuProduk`.

`{...p}` mengirim semua properti produk sebagai props. Properti yang tidak dipakai komponen (misalnya `kategori`) diabaikan saja.

cards.code:
const produk = [
  { id: 1, nama: 'Kopi Susu', kategori: 'Minuman', harga: 15000, stok: 12 },
  { id: 2, nama: 'Teh Melati', kategori: 'Minuman', harga: 8000, stok: 0 },
  { id: 3, nama: 'Roti Bakar', kategori: 'Makanan', harga: 12000, stok: 4, diskon: 25 },
  { id: 4, nama: 'Pisang Goreng', kategori: 'Makanan', harga: 10000, stok: 9 },
];

function Bagian({ judul, children }) {
  return (
    <section className="bagian">
      <h3>{judul}</h3>
      <ul>{children}</ul>
    </section>
  );
}

function KartuProduk({ nama, harga, stok, diskon = 0 }) {
  const hargaAkhir = harga - (harga * diskon) / 100;
  return (
    <li>
      <b>{nama}</b> Rp{hargaAkhir.toLocaleString('id-ID')}
      {diskon > 0 && <em> (Hemat {diskon}%)</em>}
      {' · '}
      {stok > 0 ? `Sisa ${stok}` : 'Habis'}
    </li>
  );
}

export default function App() {
  const kategori = [...new Set(produk.map((p) => p.kategori))];
  return (
    <div>
      <h2>Katalog Toko Budi</h2>
      {kategori.map((k) => (
        <Bagian key={k} judul={k}>
          {produk
            .filter((p) => p.kategori === k)
            .map((p) => <KartuProduk key={p.id} {...p} />)}
        </Bagian>
      ))}
    </div>
  );
}

