function Kartu({ nama, harga, diskon = 0 }) {
  const akhir = harga - (harga * diskon) / 100;
  return <p>{nama}: Rp{akhir}</p>;
}

const roti = { id: 3, nama: 'Roti', harga: 12000, diskon: 25 };

export default function App() {
  return <Kartu {...roti} />;
}

function Stok({ stok }) {
  return <p>{stok > 0 ? `Sisa ${stok}` : 'Habis'}</p>;
}

export default function App() {
  return <Stok stok={0} />;
}
